<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Password Strength Checker Online','description'=>'Check password length, character variety and estimated strength locally in your browser.','url'=>'https://smarttoolz.in/tools/password-strength-checker/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">PASSWORD SECURITY</span><h1>Password Strength Checker</h1><p>Evaluate password strength without sending the password anywhere.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Password<input id="p" type="password" placeholder="Enter password"></label><button id="go" class="tool-btn">Check Strength</button><p id="out" style="font-size:20px;font-weight:800"></p></div></section></main><script>(()=>{const p=document.getElementById('p'),o=document.getElementById('out');document.getElementById('go').onclick=()=>{let s=p.value,n=0;n+=s.length>=12?2:s.length>=8?1:0;n+=/[a-z]/.test(s)+/[A-Z]/.test(s)+/\d/.test(s)+/[^A-Za-z0-9]/.test(s);o.textContent=s?`Strength: ${n>=6?'Strong':n>=4?'Medium':n>=2?'Weak':'Very weak'} · ${s.length} characters`:'Enter a password.'}})();</script><?php smarttoolz_tool_page_end(); ?>